SELECT CASE WHEN budget >= 3193000 THEN 'HIGH' ELSE 'LOW' END AS budget_tier, location, COUNT(CASE WHEN location = 'Bangkok' THEN 1 END) AS bangkok_count, SIZE(COLLECT_SET(dept_name)) AS num_dept_names, SORT_ARRAY(COLLECT_SET(dept_name)) AS dept_name_list, COUNT_IF(location = 'New York') AS new_york_events FROM departments GROUP BY ROLLUP (CASE WHEN budget >= 3193000 THEN 'HIGH' ELSE 'LOW' END, location) ORDER BY new_york_events DESC NULLS FIRST;
